type Severity = 'info' | 'warning' | 'error';

interface AlertProps {
  severity: Severity;
  message: string;
  onDismiss?: () => void;
}

const icons: Record<Severity, string> = { info: 'i', warning: '!', error: 'x' };

export function Alert({ severity, message, onDismiss }: AlertProps) {
  const children: object[] = [
    { type: 'span', props: { className: 'icon' }, children: [icons[severity]] },
    { type: 'p', props: {}, children: [message] },
  ];
  if (onDismiss) {
    children.push({ type: 'button', props: { onClick: onDismiss }, children: ['×'] });
  }
  return {
    type: 'div',
    props: {
      className: 'alert alert-' + severity,
      role: severity === 'error' ? 'alert' : 'status',
    },
    children,
  };
}

