export function childStats(children: (Element | string)[]) {
  let textNodes = 0;
  let elements = 0;
  let totalTextLength = 0;
  for (const child of children) {
    if (typeof child === 'string') {
      textNodes++;
      totalTextLength += child.length;
    } else {
      elements++;
    }
  }
  return { textNodes, elements, totalTextLength };
}

