    type: 'div',
    props: { className: 'searchbox' },
    children: [
      {
        type: 'input',
        props: {
          value,
          disabled,
          onInput: (e: { target: { value: string } }) => onChange(e.target.value),
          onKeyDown: (e: { key: string; target: { value: string } }) => {
            if (e.key === 'Enter') onSearch(e.target.value);
          },
        },
        children: [],
      },
      {
        type: 'button',
        props: {
          disabled,
          onClick: () => {
            if (!disabled) onSearch(value);
          },
        },
        children: ['Search'],
      },
    ],
  };
}

