bootforge/react-ts/typed-components/gene.solution:
interface ColumnDef<T> { header: string; cell: (row: T) => string }

interface TableProps<T> {
  columns: ColumnDef<T>[];
  rows: T[];
  getRowKey: (row: T) => string;
  emptyMessage?: string;
}

export function Table<T>({ columns, rows, getRowKey, emptyMessage = 'No data' }: TableProps<T>) {
  const headRow = {
    type: 'tr',
    props: {},
    children: columns.map((col) => ({ type: 'th', props: {}, children: [col.header] })),
  };
  const bodyChildren = rows.length
    ? rows.map((row) => ({
        type: 'tr',
        props: { key: getRowKey(row) },
        children: columns.map((col) => ({ type: 'td', props: {}, children: [col.cell(row)] })),
      }))
    : [
        {
          type: 'tr',
          props: {},
          children: [{ type: 'td', props: { colSpan: columns.length }, children: [emptyMessage] }],
        },
      ];
  return {
    type: 'table',
    props: {},
    children: [
      { type: 'thead', props: {}, children: [headRow] },
      { type: 'tbody', props: {}, children: bodyChildren },
    ],
  };
}

