interface ListLogic<T> {
  items: T[];
  count: number;
  isEmpty: boolean;
  add: (item: T) => ListLogic<T>;
  removeAt: (index: number) => ListLogic<T>;
  clear: () => ListLogic<T>;
}

export function makeListLogic<T>(items: T[]): ListLogic<T> {
  const self: ListLogic<T> = {
    items,
    count: items.length,
    isEmpty: items.length === 0,
    add: (item: T) => makeListLogic([...items, item]),
    removeAt: (index: number) => {
      if (index < 0 || index >= items.length) return self;
      return makeListLogic(items.filter((_, i) => i !== index));
    },
    clear: () => makeListLogic([]),
  };
  return self;
}

