interface PaginationLogic {
  page: number;
  totalPages: number;
  canPrev: boolean;
  canNext: boolean;
  next: () => PaginationLogic;
  prev: () => PaginationLogic;
  goTo: (p: number) => PaginationLogic;
  slice: <T>(items: T[]) => T[];
}

export function makePaginationLogic(
  totalItems: number,
  pageSize: number,
  page: number = 1
): PaginationLogic {
  const totalPages = Math.max(1, Math.ceil(totalItems / pageSize));
  const current = Math.min(totalPages, Math.max(1, page));
  const start = (current - 1) * pageSize;
  return {
    page: current,
    totalPages,
    canPrev: current > 1,
    canNext: current < totalPages,
    next: () => makePaginationLogic(totalItems, pageSize, current + 1),
    prev: () => makePaginationLogic(totalItems, pageSize, current - 1),
    goTo: (p: number) => makePaginationLogic(totalItems, pageSize, p),
    slice: <T,>(items: T[]) => items.slice(start, start + pageSize),
  };
}

