interface History<S> { past: S[]; present: S; future: S[] }

export function withHistory<S, A extends { type: string }>(
  reducer: (s: S, a: A) => S
) {
  return function (h: History<S>, action: A | { type: 'undo' } | { type: 'redo' }): History<S> {
    if (action.type === 'undo') {
      if (h.past.length === 0) return h;
      return {
        past: h.past.slice(0, -1),
        present: h.past[h.past.length - 1],
        future: [h.present, ...h.future],
      };
    }
    if (action.type === 'redo') {
      if (h.future.length === 0) return h;
      return {
        past: [...h.past, h.present],
        present: h.future[0],
        future: h.future.slice(1),
      };
    }
    const next = reducer(h.present, action as A);
    if (Object.is(next, h.present)) return h;
    return { past: [...h.past, h.present], present: next, future: [] };
  };
}

