interface ApiResponse {
  data: {
    posts: Array<{
      post_id: string;
      title: string | null;
      author: { user_id: string; display_name: string | null } | null;
      like_count: number | null;
    }>;
  };
  meta: { page: number; total_pages: number } | null;
}

interface PostVM { id: string; title: string; authorName: string; likes: number }

export function toFeedVM(res: ApiResponse) {
  const byId: Record<string, PostVM> = {};
  const allIds: string[] = [];
  for (const p of res.data.posts) {
    const vm: PostVM = {
      id: p.post_id,
      title: p.title ?? '(untitled)',
      authorName: p.author?.display_name ?? 'unknown',
      likes: p.like_count ?? 0,
    };
    if (!(vm.id in byId)) allIds.push(vm.id);
    byId[vm.id] = vm;
  }
  return {
    posts: { byId, allIds },
    page: res.meta?.page ?? 1,
    totalPages: res.meta?.total_pages ?? 1,
  };
}

