export function validateAll<T extends Record<string, string>>(
  values: T,
  rules: { [K in keyof T]?: Array<(v: string) => string | null> }
): Partial<Record<keyof T & string, string>> {
  const errors: Partial<Record<keyof T & string, string>> = {};
  for (const field of Object.keys(rules) as Array<keyof T & string>) {
    const fieldRules = rules[field];
    if (!fieldRules) continue;
    for (const rule of fieldRules) {
      const message = rule(values[field]);
      if (message !== null) {
        errors[field] = message;
        break;
      }
    }
  }
  return errors;
}

