interface RegValues { email: string; password: string; confirm: string }

type RegErrors = Partial<Record<'email' | 'password' | 'confirm', string>>;

export function validateRegistration(values: RegValues): RegErrors {
  const errors: RegErrors = {};
  const email = values.email.trim();
  if (email === '') {
    errors.email = 'Required';
  } else {
    const at = email.indexOf('@');
    const valid = at > 0 && email.indexOf('@', at + 1) === -1 && email.slice(at + 1).includes('.');
    if (!valid) errors.email = 'Invalid email';
  }
  if (values.password === '') {
    errors.password = 'Required';
  } else if (values.password.length < 8) {
    errors.password = 'Must be at least 8 characters';
  } else if (values.confirm !== values.password) {
    errors.confirm = 'Passwords do not match';
  }
  return errors;
}

export function submitRegistration(
  values: RegValues
): { ok: false; errors: RegErrors } | { ok: true; payload: { email: string; password: string } } {
  const errors = validateRegistration(values);
  if (Object.keys(errors).length > 0) {
    return { ok: false, errors };
  }
  return {
    ok: true,
    payload: { email: values.email.trim().toLowerCase(), password: values.password },
  };
}
